```json
{
  "clarified": "对豆包爱学做全面竞品调研，覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态(重点近半年)等维度，信息来源以公开资料为主，最终形成达到竞品分析认知深度的完整产品印象，不需要正式文档格式但需有文字记录验证认知完整性。",
  "deliverable_type": "research",
  "iterative": true,
  "acceptance": [
    "覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态六大维度",
    "近期动态聚焦最近半年(2024下半年至2025初)的更新、改版、重要功能上线",
    "信息来源标注清楚，以官方公告、媒体报道、应用商店信息等公开资料为主",
    "各维度有具体事实和数据支撑，而非泛泛而谈",
    "形成对豆包爱学的完整产品印象，达到竞品分析所需的认知深度"
  ],
  "capabilities": [
    {
      "id": "plan_outline",
      "name": "规划调研大纲",
      "kind": "light",
      "desc": "根据调研目标，规划豆包爱学竞品分析的调研大纲，确定调研维度、每个维度的调研方向和关键问题清单，写入 blackboard 的 report_outline。不搜索、不产出文件，只做结构规划。",
      "outputs": [],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "大纲覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态六个维度，每个维度有明确调研方向和关键问题",
          "target": ""
        }
      ],
      "updates": ["report_outline"],
      "instances": [],
      "context_inputs": []
    },
    {
      "id": "search",
      "name": "搜索调研",
      "kind": "agent",
      "desc": "按大纲中对应维度的调研方向，搜索豆包爱学的公开信息。边搜边把原始结果追加写入文件，搜到一条写一条，每条标注来源链接和日期。不要求结构化、不要求整理——只负责收集原始素材。",
      "agent": "researcher",
      "outputs": [
        {
          "path": "solution/search/{instance}.md",
          "desc": "该维度的原始搜索结果，每条标注来源",
          "role": "evidence",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "file_exists",
          "desc": "搜索结果文件存在",
          "target": "solution/search/{instance}.md"
        },
        {
          "method": "llm_rubric",
          "desc": "搜索结果包含与该维度相关的有效信息，且每条信息标注了来源",
          "target": ""
        }
      ],
      "updates": ["search_remaining"],
      "instances": [
        {
          "name": "positioning",
          "scope": "豆包爱学的产品定位(教育AI助教/学习工具等)、目标用户群体(学生/家长/教师)、教育阶段覆盖(小学/初中/高中/大学)、核心使用场景",
          "excludes": "具体功能模块详情、商业模式定价、近半年更新迭代动态"
        },
        {
          "name": "features",
          "scope": "产品形态(APP/小程序/Web端等)、核心功能模块(拍照搜题/AI辅导/作业批改等)、交互方式与技术亮点、与竞品的功能差异",
          "excludes": "产品定位分析、商业模式定价、近半年更新迭代动态"
        },
        {
          "name": "business",
          "scope": "定价策略与收费模式(免费/会员/付费功能)、盈利方式、用户付费点设计、与竞品的价格对比",
          "excludes": "产品功能详情、产品定位分析、近半年更新迭代动态"
        },
        {
          "name": "dynamics",
          "scope": "近半年(2024下半年至2025初)的重要更新、版本迭代、功能上线、市场推广动作、融资/合作等事件",
          "excludes": "产品基础定位介绍、功能模块详情、商业模式定价"
        }
      ],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "write_evidence",
      "name": "整理证据",
      "kind": "agent",
      "desc": "从对应维度的 search 原始文件中读取搜索结果，整理成结构化的证据文件。按子主题归类，提炼关键事实和数据，保留来源标注。只整理不搜索——有明确输入(search文件)和明确产出(evidence文件)。",
      "agent": "researcher",
      "outputs": [
        {
          "path": "solution/evidence/{instance}.md",
          "desc": "该维度的结构化证据，按子主题归类，保留来源",
          "role": "intermediate",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "file_exists",
          "desc": "证据文件存在",
          "target": "solution/evidence/{instance}.md"
        },
        {
          "method": "llm_rubric",
          "desc": "证据文件按子主题结构化整理，关键事实有来源标注，内容与该维度scope相关",
          "target": ""
        }
      ],
      "updates": ["write_evidence_remaining", "evidence_index"],
      "instances": [
        {
          "name": "positioning",
          "scope": "整理产品定位、目标用户、教育阶段、使用场景的结构化证据",
          "excludes": "功能模块详情、商业模式、近期动态"
        },
        {
          "name": "features",
          "scope": "整理产品形态、核心功能、交互方式、技术亮点的结构化证据",
          "excludes": "产品定位分析、商业模式、近期动态"
        },
        {
          "name": "business",
          "scope": "整理定价策略、收费模式、盈利方式、价格对比的结构化证据",
          "excludes": "产品功能详情、产品定位、近期动态"
        },
        {
          "name": "dynamics",
          "scope": "整理近半年重要更新、版本迭代、功能上线、市场动作的结构化证据",
          "excludes": "产品基础定位、功能详情、商业模式"
        }
      ],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "synthesize",
      "name": "综合认知备忘录",
      "kind": "agent",
      "desc": "从所有维度的 evidence 文件综合提炼，写成一份完整的产品认知备忘录。不是正式竞品报告，而是帮助形成完整产品印象的结构化认知文档。搜到的用真实来源，搜不到的用趋势推演并标注。覆盖六大维度的关键认知点，形成对产品的整体判断。",
      "agent": "writer",
      "outputs": [
        {
          "path": "solution/product_brief.md",
          "desc": "豆包爱学产品认知备忘录，覆盖六大维度的综合分析",
          "role": "deliverable",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "备忘录覆盖产品定位、目标用户、产品形态、核心功能、商业模式、近期动态六个维度，各维度有具体事实支撑",
          "target": ""
        },
        {
          "method": "llm_rubric",
          "desc": "形成了对产品的整体判断和印象，而非信息的简单罗列",
          "target": ""
        }
      ],
      "updates": ["product_summary"],
      "instances": [],
      "context_inputs": ["report_outline", "evidence_index"]
    },
    {
      "id": "polish_report",
      "name": "润色优化",
      "kind": "agent",
      "desc": "读产品认知备忘录初稿，做语言精炼、逻辑连贯、信息密度优化。确保各维度之间的关联性清晰(如产品定位如何决定功能设计、商业模式如何匹配目标用户)，删除冗余，补强薄弱环节。",
      "agent": "writer",
      "outputs": [
        {
          "path": "solution/product_brief.md",
          "desc": "润色后的产品认知备忘录",
          "role": "deliverable",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "语言精炼、逻辑连贯、各维度关联清晰、无冗余重复",
          "target": ""
        }
      ],
      "updates": [],
      "instances": [],
      "context_inputs": ["report_outline"]
    },
    {
      "id": "review_report",
      "name": "审校验收",
      "kind": "agent",
      "desc": "审校最终备忘录是否满足全部验收标准：六大维度是否全覆盖、近期动态是否聚焦近半年、信息来源是否标注、是否形成完整产品印象而非信息罗列。不通过则指出具体缺口。",
      "agent": "reviewer",
      "outputs": [
        {
          "path": "solution/review_notes.md",
          "desc": "审校意见，列出满足和不满足的标准",
          "role": "intermediate",
          "materializable": true
        }
      ],
      "checks": [
        {
          "method": "llm_rubric",
          "desc": "审校意见明确列出每个验收标准的通过/不通过状态，不通过的有具体缺口说明",
          "target": ""
        }
      ],
      "updates": [],
      "instances": [],
      "context_inputs": ["report_outline"]
    }
  ],
  "guardrails": {
    "max_iterations": 15,
    "soft": [
      {
        "id": "search_depth",
        "desc": "某个维度搜索结果过于稀少(少于3条有效信息)时，提示可能需要换关键词或扩展来源",
        "action": "stop_human"
      },
      {
        "id": "product_identity",
        "desc": "豆包爱学与豆包APP的边界不清晰，无法确认是否为独立产品时需停下确认",
        "action": "stop_human"
      }
    ],
    "human_checkpoint_every": 0
  },
  "blackboard_schema": {
    "fields": [
      {
        "key": "report_outline",
        "desc": "调研大纲：六大维度及每个维度的调研方向、关键问题清单",
        "bounded": false
      },
      {
        "key": "search_remaining",
        "desc": "未完成的 search 实例列表",
        "bounded": true
      },
      {
        "key": "write_evidence_remaining",
        "desc": "未完成的 write_evidence 实例列表",
        "bounded": true
      },
      {
        "key": "evidence_index",
        "desc": "已完成的 evidence 文件路径索引，供 synthesize 读取",
        "bounded": true
      },
      {
        "key": "product_summary",
        "desc": "产品综合认知摘要(synthesize后更新)，供后续节点参考",
        "bounded": true
      }
    ]
  },
  "entry_node": "plan_outline",
  "completion_criteria": [
    "六大维度(产品定位、目标用户、产品形态、核心功能、商业模式、近期动态)均有结构化证据和综合分析",
    "近期动态聚焦最近半年且有具体事件/更新记录",
    "产品认知备忘录形成对产品的整体判断而非信息罗列",
    "review_report 审校通过所有验收标准"
  ],
  "hard_constraints": [
    "覆盖六大维度：产品定位、目标用户、产品形态、核心功能、商业模式、近期动态",
    "近期动态时间范围为最近半年(2024下半年至2025初)",
    "信息来源以公开资料为主：官方公告、媒体报道、应用商店信息",
    "每条关键信息需标注来源",
    "搜索和整理分离：search只收集原始素材，write_evidence只整理不搜索"
  ],
  "soft_guidance": [
    "产出为认知备忘录风格，不需要正式竞品报告格式",
    "侧重形成完整产品印象和整体判断，而非穷举所有细节",
    "各维度之间的关联性(定位→功能→商业模式)需体现",
    "与竞品(如其他AI教育产品)的简要对比有助于理解定位，但不展开深度竞品分析"
  ],
  "deliverable_contract": {
    "required_sections": [],
    "forbidden_patterns": ["无来源标注的断言性结论", "泛泛而谈缺乏具体事实的段落", "与豆包APP混淆不分的产品描述"]
  },
  "agents": ["researcher", "writer", "reviewer"],
  "required_capabilities": ["web"]
}
```
